DO $$ 
DECLARE 
    date_offset INT;
BEGIN
    -- Calculate difference in days between Today and 2026-09-14
    SELECT (CURRENT_DATE - '2026-09-14'::DATE) INTO date_offset;

    -- Shift Hotspot acquisition dates
    UPDATE hotspot 
    SET acq_date = acq_date + (date_offset || ' days')::INTERVAL;

    -- Shift Weather dates and re-evaluate is_forecast status dynamically
    UPDATE weather 
    SET 
        acq_date = acq_date + (date_offset || ' days')::INTERVAL,
        target_date = target_date + (date_offset || ' days')::INTERVAL,
        is_forecast = ((target_date + (date_offset || ' days')::INTERVAL) > CURRENT_DATE);

    -- Shift Fire Prediction timestamps
    UPDATE fire_prediction 
    SET forecast_timestamp = forecast_timestamp + (date_offset || ' days')::INTERVAL;

    RAISE NOTICE 'Dates updated successfully! 2026-09-13 is now Yesterday relative to today.';
END $$;
